p = 'src/tests/base/test_memberships.py'
s = open(p).read()
s = s.replace("""from django_scopes import scope
from freezegun import freeze_time
""", """from django_scopes import scope
from freezegun import freeze_time
""")
s = s.replace("""from pretix.base.services.memberships import (
    membership_validity,
)""", """from pretix.base.services.memberships import (
    membership_validity, validate_memberships_in_order,
)""")
s = s.replace("""from pretix.base.models import (
