)""", """from pretix.base.models import (
    CartPosition, Event, Item, Order, OrderPosition, Organizer,
)""")
s += '''

def _position(item, membership=None, subevent=None, valid_from=None):
    return OrderPosition(item=item, price=23, used_membership=membership, subevent=subevent, valid_from=valid_from)


@pytest.fixture
def existing_order(event, customer):
    return event.orders.create(
        code='EXISTING', email='dummy@example.org', status=Order.STATUS_PAID, datetime=now(), expires=now(),
        total=Decimal('23.00'), customer=customer, locale='en',
        sales_channel=event.organizer.sales_channels.get(identifier='web'),
    )


@pytest.mark.django_db
def test_validate_memberships_ignores_items_not_requiring_membership(event, customer):
    item = Item.objects.create(event=event, name='Plain', default_price=Decimal('23.00'))
    validate_memberships_in_order(None, [_position(item)], event)
    validate_memberships_in_order(customer, [_position(item)], event, lock=True)


@pytest.mark.django_db
def test_validate_memberships_valid(event, customer, membership, requiring_ticket):
    validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event, lock=True)


@pytest.mark.django_db
def test_validate_memberships_missing_membership(event, customer, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_position(requiring_ticket)], event)
    assert 'membership' in str(excinfo.value.message)


@pytest.mark.django_db
def test_validate_memberships_no_customer(event, membership, requiring_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(None, [_position(requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_other_customers_membership(event, customer, requiring_ticket, membership_type):
    other = event.organizer.customers.create(email="jane@example.org")
    foreign = other.memberships.create(
        membership_type=membership_type,
        date_start=datetime(2021, 4, 1, 0, 0, 0, 0, tzinfo=TZ),
        date_end=datetime(2021, 4, 30, 23, 59, 59, 999999, tzinfo=TZ),
    )
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, foreign)], event)


@pytest.mark.django_db
def test_validate_memberships_canceled(event, customer, membership, requiring_ticket):
    membership.canceled = True
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_wrong_testmode(event, customer, membership, requiring_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event, testmode=True)


@pytest.mark.django_db
def test_validate_memberships_type_not_allowed(event, customer, requiring_ticket):
    other_type = event.organizer.membership_types.create(name="Other")
    m = customer.memberships.create(
        membership_type=other_type,
        date_start=datetime(2021, 4, 1, 0, 0, 0, 0, tzinfo=TZ),
        date_end=datetime(2021, 4, 30, 23, 59, 59, 999999, tzinfo=TZ),
    )
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, m)], event)


@pytest.mark.django_db
def test_validate_memberships_date_of_ticket(event, customer, membership, requiring_ticket):
    membership.date_end = datetime(2221, 4, 30, 23, 59, 59, 999999, tzinfo=TZ)
    membership.save()
    later = datetime(2222, 1, 1, 10, 0, 0, 0, tzinfo=TZ)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, membership, valid_from=later)], event)
    # Start date not chosen yet: only the end of the membership matters
    validate_memberships_in_order(customer, [_position(requiring_ticket, membership, valid_from=later)], event,
                                  valid_from_not_chosen=True)


@pytest.mark.django_db
def test_validate_memberships_max_usages_within_batch(event, customer, membership, requiring_ticket, membership_type):
    membership_type.max_usages = 1
    membership_type.save()
    validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [
            _position(requiring_ticket, membership),
            _position(requiring_ticket, membership),
        ], event)


@pytest.mark.django_db
def test_validate_memberships_max_usages_existing_order(event, customer, membership, requiring_ticket, membership_type,
                                                        existing_order):
    membership_type.max_usages = 1
    membership_type.save()
    OrderPosition.objects.create(order=existing_order, item=requiring_ticket, price=23, used_membership=membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event)
    # When the existing order is the one being changed, its own usage does not count
    validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event,
                                  ignored_order=existing_order)


@pytest.mark.django_db
def test_validate_memberships_parallel_usage_within_batch(event, customer, membership, requiring_ticket, subevent):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [
            _position(requiring_ticket, membership),
            _position(requiring_ticket, membership),
        ], event)
    # Different start time is fine
    validate_memberships_in_order(customer, [
        _position(requiring_ticket, membership),
        _position(requiring_ticket, membership, subevent=subevent),
    ], event)


@pytest.mark.django_db
def test_validate_memberships_parallel_usage_existing_order(event, customer, membership, requiring_ticket,
                                                            existing_order):
    OrderPosition.objects.create(order=existing_order, item=requiring_ticket, price=23, used_membership=membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event)
    validate_memberships_in_order(customer, [_position(requiring_ticket, membership)], event,
                                  ignored_order=existing_order)


@pytest.mark.django_db
def test_validate_memberships_parallel_usage_allowed(event, customer, membership, requiring_ticket, membership_type):
    membership_type.allow_parallel_usage = True
    membership_type.save()
    validate_memberships_in_order(customer, [
        _position(requiring_ticket, membership),
        _position(requiring_ticket, membership),
    ], event)
'''
